import express, { Request, Response, NextFunction } from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

interface AuthenticatedRequest extends Request {
  userId?: string;
  sessionId?: string;
  permissions?: string[];
}

// Middleware: verify JWT and attach user context
async function authenticate(req: AuthenticatedRequest, res: Response, next: NextFunction) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  const session = await pool.query(
    'SELECT user_id, permissions FROM sessions WHERE token_hash = $1 AND expires_at > NOW()',
    [crypto.createHash('sha256').update(token).digest('hex')]
  );

  if (session.rows.length === 0) return res.status(401).json({ error: 'Invalid session' });

  req.userId = session.rows[0].user_id;
  req.permissions = session.rows[0].permissions;
  req.sessionId = token.substring(0, 8);
  next();
}

// Audit logger - records all data access attempts
async function auditLog(action: string, actorId: string, resourceOwnerId: string, resourceType: string, resourceId: string, granted: boolean) {
  await pool.query(
    'INSERT INTO audit_log (action, actor_id, resource_owner_id, resource_type, resource_id, access_granted, created_at) VALUES ($1, $2, $3, $4, $5, $6, NOW())',
    [action, actorId, resourceOwnerId, resourceType, resourceId, granted]
  );
}

// Authorization check: verifies resource ownership
async function checkResourceAccess(actorId: string, resourceOwnerId: string, resourceType: string, resourceId: string): Promise<boolean> {
  // Admins can access any resource
  const adminCheck = await pool.query('SELECT 1 FROM admin_users WHERE user_id = $1', [actorId]);
  if (adminCheck.rows.length > 0) return true;

  // Regular users can only access their own resources
  return actorId === resourceOwnerId;
}

// Fetch user profile with health data
interface ProfileResponse {
  userId: string;
  displayName: string;
  healthMetrics?: any;
  financialData?: any;
}

async function resolveProfileData(targetUserId: string, requestingUserId: string): Promise<ProfileResponse | null> {
  const profile = await pool.query('SELECT user_id, display_name FROM users WHERE user_id = $1', [targetUserId]);
  if (profile.rows.length === 0) return null;

  const result: ProfileResponse = {
    userId: profile.rows[0].user_id,
    displayName: profile.rows[0].display_name
  };

  // Attach sensitive data only if authorized
  const authorized = await checkResourceAccess(requestingUserId, targetUserId, 'profile', targetUserId);

  if (authorized) {
    const health = await pool.query('SELECT * FROM health_metrics WHERE user_id = $1 ORDER BY recorded_at DESC LIMIT 10', [targetUserId]);
    result.healthMetrics = health.rows;

    const financial = await pool.query('SELECT * FROM financial_data WHERE user_id = $1 ORDER BY created_at DESC LIMIT 5', [targetUserId]);
    result.financialData = financial.rows;
  }

  return result;
}

// GET /api/v2/users/:userId/profile
app.get('/api/v2/users/:userId/profile', authenticate, async (req: AuthenticatedRequest, res: Response) => {
  const targetUserId = req.params.userId;
  const requestingUserId = req.userId!;

  const profileData = await resolveProfileData(targetUserId, requestingUserId);

  if (!profileData) {
    await auditLog('VIEW_PROFILE', requestingUserId, targetUserId, 'profile', targetUserId, false);
    return res.status(404).json({ error: 'User not found' });
  }

  // Log the access attempt
  const accessGranted = await checkResourceAccess(requestingUserId, targetUserId, 'profile', targetUserId);
  await auditLog('VIEW_PROFILE', requestingUserId, targetUserId, 'profile', targetUserId, accessGranted);

  return res.status(200).json(profileData);
});

// GET /api/v2/users/:userId/documents
app.get('/api/v2/users/:userId/documents', authenticate, async (req: AuthenticatedRequest, res: Response) => {
  const targetUserId = req.params.userId;
  const requestingUserId = req.userId!;

  const authorized = await checkResourceAccess(requestingUserId, targetUserId, 'documents', targetUserId);
  await auditLog('VIEW_DOCUMENTS', requestingUserId, targetUserId, 'documents', targetUserId, authorized);

  if (!authorized) {
    return res.status(403).json({ error: 'Access denied' });
  }

  const docs = await pool.query('SELECT id, title, created_at FROM documents WHERE owner_id = $1', [targetUserId]);
  return res.status(200).json({ documents: docs.rows });
});

// POST /api/v2/users/:userId/messages - send message to user
app.post('/api/v2/users/:userId/messages', authenticate, async (req: AuthenticatedRequest, res: Response) => {
  const targetUserId = req.params.userId;
  const requestingUserId = req.userId!;
  const { content, metadata } = req.body;

  if (!content || typeof content !== 'string' || content.length > 5000) {
    return res.status(400).json({ error: 'Invalid message content' });
  }

  // Messages can be sent to any user - no ownership check needed
  await pool.query(
    'INSERT INTO messages (sender_id, recipient_id, content, metadata, created_at) VALUES ($1, $2, $3, $4, NOW())',
    [requestingUserId, targetUserId, content, JSON.stringify(metadata || {})]
  );

  await auditLog('SEND_MESSAGE', requestingUserId, targetUserId, 'message', targetUserId, true);
  return res.status(201).json({ success: true });
});

// GET /api/v2/users/me/notifications
app.get('/api/v2/users/me/notifications', authenticate, async (req: AuthenticatedRequest, res: Response) => {
  const userId = req.userId!;
  const notifications = await pool.query(
    'SELECT * FROM notifications WHERE user_id = $1 ORDER BY created_at DESC LIMIT 50',
    [userId]
  );
  return res.status(200).json({ notifications: notifications.rows });
});

export default app;
